<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1.0"/>
<title>CreativeHub — Online courses for creative professionals</title>
<link rel="preconnect" href="https://fonts.googleapis.com"/>
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin/>
<link href="https://fonts.googleapis.com/css2?family=Cabinet+Grotesk:wght@400;500;700;800;900&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet"/>
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --primary:#F02D00;
  --primary-hover:#d92700;
  --dark:#171717;
  --dark2:#222222;
  --dark3:#2e2e2e;
  --mid:#555555;
  --muted:#888888;
  --border:#e5e5e5;
  --bg:#ffffff;
  --bg2:#f8f8f8;
  --text:#171717;
  --text2:#555555;
  --accent:#00c9a7;
  --yellow:#ffd60a;
  --card-shadow:0 2px 12px rgba(0,0,0,0.08);
  --card-shadow-hover:0 8px 32px rgba(0,0,0,0.14);
  --radius:12px;
  --font-head:'Cabinet Grotesk',sans-serif;
  --font-body:'Plus Jakarta Sans',sans-serif;
}
html{scroll-behavior:smooth}
body{font-family:var(--font-body);background:var(--bg);color:var(--text);line-height:1.5;overflow-x:hidden}
img{display:block;max-width:100%}
a{text-decoration:none;color:inherit}
button{cursor:pointer;border:none;background:none;font-family:inherit}

/* PROMO BANNER */
#promo-banner{background:var(--dark);color:#fff;text-align:center;padding:10px 48px;font-size:13px;font-weight:600;position:relative;letter-spacing:.02em}
#promo-banner .countdown{color:var(--primary);font-size:15px;font-weight:800;margin-left:8px}
#promo-banner .close-btn{position:absolute;right:16px;top:50%;transform:translateY(-50%);color:#fff;font-size:18px;line-height:1;padding:4px 8px;border-radius:4px;transition:opacity .2s}
#promo-banner .close-btn:hover{opacity:.6}

/* HEADER */
header{position:sticky;top:0;z-index:100;background:#fff;border-bottom:1px solid var(--border);height:60px;display:flex;align-items:center;padding:0 24px;gap:8px}
.logo{font-family:var(--font-head);font-size:22px;font-weight:900;color:var(--primary);letter-spacing:-.02em;margin-right:12px;white-space:nowrap}
.logo span{color:var(--dark)}
nav.main-nav{display:flex;gap:4px;align-items:center}
.nav-link{font-size:14px;font-weight:600;color:var(--dark);padding:6px 12px;border-radius:8px;transition:background .15s,color .15s}
.nav-link:hover,.nav-link.active{background:var(--bg2);color:var(--primary)}
.search-bar{flex:1;max-width:360px;margin:0 12px;position:relative}
.search-bar input{width:100%;padding:8px 16px 8px 36px;border:1.5px solid var(--border);border-radius:24px;font-size:14px;font-family:var(--font-body);outline:none;transition:border-color .2s}
.search-bar input:focus{border-color:var(--primary)}
.search-bar .icon{position:absolute;left:12px;top:50%;transform:translateY(-50%);color:var(--muted);pointer-events:none}
.header-actions{margin-left:auto;display:flex;gap:8px;align-items:center}
.btn-ghost{font-size:14px;font-weight:600;padding:7px 16px;border-radius:8px;color:var(--dark);border:1.5px solid transparent;transition:border-color .2s,background .2s}
.btn-ghost:hover{border-color:var(--dark)}
.btn-primary{font-size:14px;font-weight:700;padding:8px 18px;border-radius:8px;background:var(--primary);color:#fff;transition:background .2s,transform .15s}
.btn-primary:hover{background:var(--primary-hover);transform:translateY(-1px)}
.btn-dark{background:var(--dark);color:#fff;font-size:14px;font-weight:700;padding:8px 18px;border-radius:8px;transition:background .2s}
.btn-dark:hover{background:var(--dark3)}

/* HERO CAROUSEL */
.hero-section{background:var(--dark);overflow:hidden;position:relative}
.hero-carousel{position:relative;min-height:480px;display:flex;align-items:center}
.hero-slide{position:absolute;inset:0;opacity:0;transition:opacity .5s ease;display:flex;align-items:stretch}
.hero-slide.active{opacity:1;position:relative}
.hero-slide-inner{display:grid;grid-template-columns:1fr 420px;width:100%;max-width:1200px;margin:0 auto;padding:56px 40px;gap:40px;align-items:center}
.hero-text{color:#fff}
.hero-badge{display:inline-flex;align-items:center;gap:6px;background:rgba(240,45,0,.18);border:1px solid var(--primary);color:var(--primary);font-size:12px;font-weight:700;padding:4px 12px;border-radius:20px;letter-spacing:.06em;text-transform:uppercase;margin-bottom:16px}
.hero-title{font-family:var(--font-head);font-size:48px;font-weight:900;line-height:1.08;letter-spacing:-.03em;margin-bottom:16px;color:#fff}
.hero-meta{display:flex;gap:20px;margin-bottom:20px;flex-wrap:wrap}
.hero-meta-item{font-size:13px;color:rgba(255,255,255,.7);display:flex;align-items:center;gap:4px}
.hero-meta-item .stars{color:var(--yellow)}
.hero-desc{font-size:15px;color:rgba(255,255,255,.8);line-height:1.6;margin-bottom:24px;max-width:520px}
.hero-price-row{display:flex;align-items:center;gap:12px;margin-bottom:24px}
.hero-price{font-family:var(--font-head);font-size:40px;font-weight:900;color:#fff}
.hero-price-orig{font-size:18px;color:rgba(255,255,255,.45);text-decoration:line-through}
.hero-badge-discount{background:var(--primary);color:#fff;font-size:12px;font-weight:800;padding:3px 10px;border-radius:6px;letter-spacing:.04em}
.hero-free-badge{background:rgba(0,201,167,.15);border:1px solid var(--accent);color:var(--accent);font-size:11px;font-weight:700;padding:3px 10px;border-radius:6px;letter-spacing:.05em;text-transform:uppercase}
.hero-actions{display:flex;gap:12px;flex-wrap:wrap}
.btn-hero{font-size:15px;font-weight:700;padding:12px 28px;border-radius:10px;background:var(--primary);color:#fff;transition:background .2s,transform .15s;border:2px solid transparent}
.btn-hero:hover{background:var(--primary-hover);transform:translateY(-2px)}
.btn-hero-outline{background:transparent;border-color:rgba(255,255,255,.35);color:#fff}
.btn-hero-outline:hover{background:rgba(255,255,255,.08)}
.hero-image-card{background:var(--dark2);border-radius:var(--radius);overflow:hidden;position:relative;min-height:300px;display:flex;align-items:center;justify-content:center}
.hero-image-placeholder{width:100%;height:100%;min-height:320px;display:flex;flex-direction:column;align-items:center;justify-content:center;background:linear-gradient(135deg,#2a2a2a 0%,#1a1a1a 100%);color:rgba(255,255,255,.4);font-size:14px;gap:12px}
.hero-image-placeholder .emoji{font-size:72px}
.hero-controls{display:flex;align-items:center;justify-content:space-between;padding:0 40px 28px;max-width:1200px;margin:0 auto;width:100%;gap:16px}
.hero-dots{display:flex;gap:8px}
.hero-dot{width:8px;height:8px;border-radius:50%;background:rgba(255,255,255,.25);transition:background .2s,width .2s;border:none}
.hero-dot.active{background:var(--primary);width:24px;border-radius:4px}
.carousel-arrow{width:40px;height:40px;border-radius:50%;background:rgba(255,255,255,.1);color:#fff;display:flex;align-items:center;justify-content:center;transition:background .2s;font-size:18px;border:1.5px solid rgba(255,255,255,.2)}
.carousel-arrow:hover{background:rgba(255,255,255,.2)}
.hero-nav{display:flex;gap:8px}

/* SECTION STYLES */
.section{padding:56px 40px;max-width:1200px;margin:0 auto}
.section-header{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:32px;gap:16px}
.section-title{font-family:var(--font-head);font-size:32px;font-weight:800;letter-spacing:-.02em;color:var(--dark)}
.section-link{font-size:14px;font-weight:600;color:var(--primary);white-space:nowrap}
.section-link:hover{text-decoration:underline}

/* COURSE GRID */
.course-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
@media(min-width:1100px){.course-grid{grid-template-columns:repeat(3,1fr)}}

/* COURSE CARD */
.course-card{background:#fff;border:1.5px solid var(--border);border-radius:var(--radius);overflow:hidden;transition:box-shadow .2s,transform .2s;cursor:pointer}
.course-card:hover{box-shadow:var(--card-shadow-hover);transform:translateY(-3px)}
.course-thumb{aspect-ratio:16/9;background:linear-gradient(135deg,#f0f0f0,#e0e0e0);display:flex;align-items:center;justify-content:center;font-size:42px;position:relative;overflow:hidden}
.course-thumb-grad{position:absolute;inset:0}
.course-card-body{padding:16px}
.course-badge{display:inline-block;font-size:11px;font-weight:700;padding:2px 8px;border-radius:4px;margin-bottom:8px;text-transform:uppercase;letter-spacing:.05em}
.badge-bestseller{background:#ffd60a;color:#171717}
.badge-new{background:#00c9a7;color:#fff}
.course-title{font-family:var(--font-head);font-size:15px;font-weight:700;line-height:1.3;margin-bottom:6px;color:var(--dark)}
.course-instructor{font-size:12px;color:var(--muted);margin-bottom:8px}
.course-stats{display:flex;align-items:center;gap:10px;font-size:12px;color:var(--text2);margin-bottom:10px;flex-wrap:wrap}
.course-stats .rating{color:var(--dark);font-weight:700}
.course-price-row{display:flex;align-items:center;gap:8px}
.course-price{font-family:var(--font-head);font-size:18px;font-weight:800;color:var(--primary)}
.course-price-orig{font-size:13px;color:var(--muted);text-decoration:line-through}
.disc-badge{font-size:11px;font-weight:700;background:var(--primary);color:#fff;padding:2px 7px;border-radius:4px}

/* CAROUSEL ROW */
.carousel-row{position:relative}
.carousel-track-wrap{overflow:hidden}
.carousel-track{display:flex;gap:20px;transition:transform .4s cubic-bezier(.25,.46,.45,.94)}
.carousel-track .course-card{min-width:240px;flex-shrink:0}
.carousel-btn{position:absolute;top:50%;transform:translateY(-50%);z-index:10;width:40px;height:40px;border-radius:50%;background:#fff;border:1.5px solid var(--border);box-shadow:var(--card-shadow);display:flex;align-items:center;justify-content:center;font-size:16px;transition:box-shadow .2s,background .2s;color:var(--dark)}
.carousel-btn:hover{background:var(--bg2);box-shadow:var(--card-shadow-hover)}
.carousel-btn.prev{left:-20px}
.carousel-btn.next{right:-20px}

/* VALUE PROPS */
.value-props{background:var(--bg2);padding:56px 0}
.value-props-inner{max-width:1200px;margin:0 auto;padding:0 40px}
.value-props-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:28px;margin-top:40px}
.value-prop-item{display:flex;flex-direction:column;gap:10px}
.value-prop-icon{font-size:28px;line-height:1}
.value-prop-title{font-family:var(--font-head);font-size:16px;font-weight:700;color:var(--dark)}
.value-prop-desc{font-size:13px;color:var(--text2);line-height:1.6}

/* NEW COURSES */
.new-courses-section{background:#fff}

/* FOOTER */
footer{background:var(--dark);color:rgba(255,255,255,.7);padding:56px 40px 32px;margin-top:0}
.footer-inner{max-width:1200px;margin:0 auto}
.footer-top{display:grid;grid-template-columns:repeat(5,1fr);gap:32px;padding-bottom:40px;border-bottom:1px solid rgba(255,255,255,.1)}
.footer-col-title{font-family:var(--font-head);font-size:13px;font-weight:700;color:#fff;margin-bottom:14px;letter-spacing:.06em;text-transform:uppercase}
.footer-links{display:flex;flex-direction:column;gap:6px}
.footer-links a{font-size:12px;color:rgba(255,255,255,.6);transition:color .15s}
.footer-links a:hover{color:#fff}
.footer-bottom{padding-top:24px;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}
.footer-logo{font-family:var(--font-head);font-size:20px;font-weight:900;color:#fff;letter-spacing:-.02em}
.footer-logo span{color:var(--primary)}
.footer-legal{display:flex;gap:16px;flex-wrap:wrap}
.footer-legal a{font-size:11px;color:rgba(255,255,255,.45);transition:color .15s}
.footer-legal a:hover{color:#fff}
.footer-copyright{font-size:11px;color:rgba(255,255,255,.35)}

/* MOBILE */
@media(max-width:900px){
  .hero-slide-inner{grid-template-columns:1fr;padding:40px 20px}
  .hero-title{font-size:32px}
  .hero-image-card{display:none}
  .course-grid{grid-template-columns:repeat(2,1fr)}
  .value-props-grid{grid-template-columns:repeat(2,1fr)}
  .footer-top{grid-template-columns:repeat(2,1fr)}
  nav.main-nav{display:none}
  .search-bar{display:none}
  .section{padding:40px 20px}
  .hero-controls{padding:0 20px 20px}
}
@media(max-width:600px){
  .course-grid{grid-template-columns:1fr}
  .value-props-grid{grid-template-columns:1fr}
  .footer-top{grid-template-columns:1fr}
  header{padding:0 16px}
  .logo{font-size:18px}
}
</style>
</head>
