<script>
// Hero carousel
(function(){
  const slides = document.querySelectorAll('.hero-slide');
  const dots = document.querySelectorAll('.hero-dot');
  let current = 0;
  let timer;
  function goTo(n){
    slides[current].classList.remove('active');
    dots[current].classList.remove('active');
    current = (n + slides.length) % slides.length;
    slides[current].classList.add('active');
    dots[current].classList.add('active');
  }
  document.getElementById('hero-next').addEventListener('click',()=>{clearInterval(timer);goTo(current+1);startTimer()});
  document.getElementById('hero-prev').addEventListener('click',()=>{clearInterval(timer);goTo(current-1);startTimer()});
  dots.forEach(d=>d.addEventListener('click',()=>{clearInterval(timer);goTo(+d.dataset.index);startTimer()}));
  function startTimer(){timer=setInterval(()=>goTo(current+1),5000)}
  startTimer();
})();

// New courses carousel
(function(){
  const track = document.getElementById('new-track');
  const cardW = 260;
  let pos = 0;
  const maxPos = ()=> track.children.length * cardW - track.parentElement.offsetWidth;
  document.getElementById('new-next').addEventListener('click',()=>{pos=Math.min(pos+cardW*2,maxPos());track.style.transform=`translateX(-${pos}px)`});
  document.getElementById('new-prev').addEventListener('click',()=>{pos=Math.max(0,pos-cardW*2);track.style.transform=`translateX(-${pos}px)`});
})();

// Countdown
(function(){
  let secs = 2*3600+47*60+31;
  function fmt(s){const h=Math.floor(s/3600);const m=Math.floor(s%3600/60);const sec=s%60;return [h,m,sec].map(v=>String(v).padStart(2,'0')).join(':')}
  const el=document.getElementById('countdown');
  if(!el)return;
  const iv=setInterval(()=>{secs--;if(secs<=0){clearInterval(iv);el.textContent='00:00:00';return}el.textContent=fmt(secs)},1000);
})();
</script>
