header{position:sticky;top:0;z-index:100;background:#fff;border-bottom:1px solid var(--border);height:60px;display:flex;align-items:center;padding:0 24px;gap:8px}
.logo{font-family:var(--font-head);font-size:22px;font-weight:900;color:var(--primary);letter-spacing:-.02em;margin-right:12px;white-space:nowrap}
