.nav-link{font-size:14px;font-weight:600;color:var(--dark);padding:6px 12px;border-radius:8px;transition:background .15s,color .15s}
.nav-link:hover,.nav-link.active{background:var(--bg2);color:var(--primary)}
.search-bar{flex:1;max-width:360px;margin:0 12px;position:relative}
.search-bar input{width:100%;padding:8px 16px 8px 36px;border:1.5px solid var(--border);border-radius:24px;font-size:14px;font-family:var(--font-body);outline:none;transition:border-color .2s}
.search-bar input:focus{border-color:var(--primary)}
.search-bar .icon{position:absolute;left:12px;top:50%;transform:translateY(-50%);color:var(--muted);pointer-events:none}
.header-actions{margin-left:auto;display:flex;gap:8px;align-items:center}
.btn-ghost{font-size:14px;font-weight:600;padding:7px 16px;border-radius:8px;color:var(--dark);border:1.5px solid transparent;transition:border-color .2s}
.btn-ghost:hover{border-color:var(--dark)}
.btn-primary{font-size:14px;font-weight:700;padding:8px 18px;border-radius:8px;background:var(--primary);color:#fff;transition:background .2s}
.btn-primary:hover{background:var(--primary-hover)}

/* HERO */
