.plus-hero::before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 50% 0%,rgba(240,45,0,.15) 0%,transparent 70%);pointer-events:none}
.plus-logo{display:inline-flex;align-items:center;gap:10px;margin-bottom:20px}
.plus-logo-mark{background:var(--primary);color:#fff;font-family:var(--font-head);font-size:13px;font-weight:800;padding:4px 12px;border-radius:6px;letter-spacing:.1em;text-transform:uppercase}
.plus-hero h1{font-family:var(--font-head);font-size:56px;font-weight:900;color:#fff;letter-spacing:-.03em;line-height:1.05;margin-bottom:16px}
.plus-hero h1 em{color:var(--primary);font-style:normal}
.plus-hero p{font-size:17px;color:rgba(255,255,255,.7);max-width:540px;margin:0 auto 32px;line-height:1.6}
.btn-hero-cta{display:inline-flex;align-items:center;gap:8px;font-size:16px;font-weight:700;padding:14px 32px;border-radius:12px;background:var(--primary);color:#fff;transition:background .2s,transform .15s}
.btn-hero-cta:hover{background:var(--primary-hover);transform:translateY(-2px)}
.hero-sub{margin-top:16px;font-size:13px;color:rgba(255,255,255,.45)}
@media(max-width:768px){.plus-hero h1{font-size:32px}.plus-hero{padding:48px 20px 48px}}

/* PRICING SECTION */
.pricing-section{max-width:700px;margin:0 auto;padding:64px 40px}
.pricing-section-title{font-family:var(--font-head);font-size:36px;font-weight:900;text-align:center;letter-spacing:-.02em;margin-bottom:32px;color:var(--dark)}

/* PRICING TOGGLE */
.pricing-toggle{display:flex;align-items:center;justify-content:center;gap:0;margin-bottom:36px;border:1.5px solid var(--border);border-radius:12px;overflow:hidden;background:var(--bg2)}
.toggle-btn{flex:1;padding:12px 24px;font-family:var(--font-head);font-size:15px;font-weight:700;color:var(--muted);background:transparent;transition:background .2s,color .2s;position:relative}
.toggle-btn.active{background:#fff;color:var(--dark);box-shadow:0 1px 6px rgba(0,0,0,.1)}

/* PRICING CARD */
.pricing-card{background:#fff;border:2px solid var(--dark);border-radius:20px;padding:36px 40px;position:relative;box-shadow:0 8px 32px rgba(0,0,0,.1)}
.save-badge{position:absolute;top:-14px;left:50%;transform:translateX(-50%);background:var(--primary);color:#fff;font-family:var(--font-head);font-size:13px;font-weight:800;padding:4px 18px;border-radius:20px;white-space:nowrap;letter-spacing:.04em;display:none}
.save-badge.show{display:block}
.pricing-plan-name{font-family:var(--font-head);font-size:13px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-bottom:8px}
.pricing-price{font-family:var(--font-head);font-size:56px;font-weight:900;color:var(--dark);letter-spacing:-.03em;line-height:1}
.pricing-price sup{font-size:24px;font-weight:700;vertical-align:top;margin-top:10px;display:inline-block}
.pricing-per{font-size:16px;font-weight:500;color:var(--muted);margin-left:4px}
.pricing-billed{font-size:14px;color:var(--muted);margin-top:8px;margin-bottom:24px}
.pricing-billed strong{color:var(--dark)}
.pricing-divider{height:1px;background:var(--border);margin:24px 0}
.pricing-credits{font-size:15px;color:var(--text2);margin-bottom:8px}
.pricing-credits strong{color:var(--dark);font-weight:700}
.pricing-cancel{font-size:13px;color:var(--muted);margin-bottom:24px}
.btn-subscribe{width:100%;padding:15px;font-family:var(--font-head);font-size:16px;font-weight:800;border-radius:12px;background:var(--primary);color:#fff;transition:background .2s,transform .15s;letter-spacing:.01em}
.btn-subscribe:hover{background:var(--primary-hover);transform:translateY(-2px)}
.pricing-footnote{font-size:12px;color:var(--muted);text-align:center;margin-top:12px;line-height:1.6}

@media(max-width:768px){.pricing-section{padding:40px 20px}.pricing-card{padding:28px 24px}.pricing-price{font-size:42px}}

/* BENEFITS SECTION */
.benefits-section{background:var(--bg2);padding:64px 40px}
.benefits-inner{max-width:1100px;margin:0 auto}
.section-title-center{font-family:var(--font-head);font-size:36px;font-weight:900;text-align:center;letter-spacing:-.02em;margin-bottom:12px}
