.benefit-icon{font-size:32px;margin-bottom:14px}
.benefit-title{font-family:var(--font-head);font-size:18px;font-weight:800;color:var(--dark);margin-bottom:8px}
.benefit-desc{font-size:14px;color:var(--text2);line-height:1.6}
.benefit-highlight{color:var(--primary);font-weight:700}

@media(max-width:768px){.benefits-section{padding:40px 20px}}

/* COURSE CATALOG CAROUSEL */
.catalog-section{padding:64px 40px;max-width:1200px;margin:0 auto}
.carousel-row{position:relative;padding:0 20px}
.carousel-track-wrap{overflow:hidden}
.carousel-track{display:flex;gap:16px;transition:transform .4s cubic-bezier(.25,.46,.45,.94)}
.carousel-btn{position:absolute;top:50%;transform:translateY(-50%);z-index:10;width:40px;height:40px;border-radius:50%;background:#fff;border:1.5px solid var(--border);box-shadow:var(--card-shadow);display:flex;align-items:center;justify-content:center;font-size:16px;transition:box-shadow .2s,background .2s;color:var(--dark)}
.carousel-btn:hover{background:var(--bg2);box-shadow:var(--card-shadow-hover)}
.carousel-btn.prev{left:0}
.carousel-btn.next{right:0}
.catalog-card{min-width:200px;flex-shrink:0;border-radius:var(--radius);overflow:hidden;border:1.5px solid var(--border);background:#fff;transition:transform .2s,box-shadow .2s;cursor:pointer}
.catalog-card:hover{transform:translateY(-3px);box-shadow:var(--card-shadow-hover)}
.catalog-thumb{aspect-ratio:4/3;display:flex;align-items:center;justify-content:center;font-size:40px}
.catalog-card-body{padding:12px 14px}
.catalog-title{font-family:var(--font-head);font-size:13px;font-weight:700;color:var(--dark);line-height:1.3;margin-bottom:4px}
.catalog-inst{font-size:11px;color:var(--muted)}
.free-tag{display:inline-block;background:rgba(0,201,167,.12);color:var(--accent);font-size:10px;font-weight:700;padding:2px 7px;border-radius:4px;margin-top:6px;letter-spacing:.05em;text-transform:uppercase}

@media(max-width:768px){.catalog-section{padding:40px 20px}}

/* CREDITS CAROUSEL */
.credits-section{background:var(--dark);padding:64px 40px}
