.cert-feature-item{display:flex;gap:10px;align-items:flex-start}
.cert-feature-icon{font-size:20px;flex-shrink:0;margin-top:2px}
.cert-feature-text{font-size:13px;color:var(--text2);line-height:1.5}
.cert-feature-text strong{display:block;font-weight:700;color:var(--dark);margin-bottom:2px}

/* COMPARISON TABLE */
.comparison-section{background:var(--bg2);padding:64px 40px}
.comparison-inner{max-width:800px;margin:0 auto}
.comparison-table{width:100%;border-collapse:collapse;margin-top:40px;background:#fff;border-radius:var(--radius);overflow:hidden;box-shadow:var(--card-shadow)}
.comparison-table th{padding:16px 24px;text-align:center;font-family:var(--font-head);font-size:15px;font-weight:800;background:var(--dark);color:#fff}
.comparison-table th:first-child{text-align:left;background:var(--dark3)}
.comparison-table th.highlight{background:var(--primary)}
.comparison-table td{padding:14px 24px;border-bottom:1px solid var(--border);font-size:14px;text-align:center;color:var(--text2)}
.comparison-table td:first-child{text-align:left;font-weight:600;color:var(--dark)}
.comparison-table tr:last-child td{border-bottom:none}
.comparison-table tr:hover td{background:var(--bg2)}
.check-yes{color:var(--accent);font-size:18px;font-weight:700}
.check-no{color:var(--border);font-size:18px}

@media(max-width:768px){.comparison-section{padding:40px 20px}.comparison-table td,.comparison-table th{padding:12px 14px;font-size:13px}}

/* FAQ */
.faq-section{padding:64px 40px;max-width:760px;margin:0 auto}
.faq-item{border-bottom:1.5px solid var(--border);overflow:hidden}
.faq-question{width:100%;display:flex;align-items:center;justify-content:space-between;padding:20px 0;font-family:var(--font-head);font-size:17px;font-weight:700;color:var(--dark);text-align:left;gap:16px;background:none;border:none;cursor:pointer}
.faq-question:hover{color:var(--primary)}
.faq-icon{font-size:20px;color:var(--primary);transition:transform .3s;flex-shrink:0;font-weight:900}
.faq-answer{max-height:0;overflow:hidden;transition:max-height .4s ease,padding .4s ease}
.faq-answer.open{max-height:400px}
.faq-answer-inner{padding-bottom:20px;font-size:15px;color:var(--text2);line-height:1.7}
.faq-item.active .faq-icon{transform:rotate(45deg)}

@media(max-width:768px){.faq-section{padding:40px 20px}.faq-question{font-size:15px}}

/* FOOTER */
footer{background:var(--dark);color:rgba(255,255,255,.7);padding:48px 40px 28px}
.footer-inner{max-width:1200px;margin:0 auto}
.footer-top{display:grid;grid-template-columns:repeat(4,1fr);gap:32px;padding-bottom:32px;border-bottom:1px solid rgba(255,255,255,.1)}
