@media(max-width:500px){.footer-top{grid-template-columns:1fr}}
.footer-col-title{font-family:var(--font-head);font-size:11px;font-weight:700;color:#fff;margin-bottom:12px;letter-spacing:.08em;text-transform:uppercase}
.footer-links{display:flex;flex-direction:column;gap:6px}
.footer-links a{font-size:12px;color:rgba(255,255,255,.55);transition:color .15s}
.footer-links a:hover{color:#fff}
.footer-bottom{padding-top:24px;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}
.footer-logo{font-family:var(--font-head);font-size:20px;font-weight:900;color:#fff}
.footer-logo span{color:var(--primary)}
.footer-legal{display:flex;gap:16px;flex-wrap:wrap}
.footer-legal a{font-size:11px;color:rgba(255,255,255,.4);transition:color .15s}
.footer-legal a:hover{color:#fff}
.footer-copyright{font-size:11px;color:rgba(255,255,255,.3)}

@media(max-width:768px){
  header{padding:0 16px}
  nav.main-nav{display:none}
  .search-bar{display:none}
  footer{padding:32px 20px 20px}
}
