function handleSubmit(e){
  e.preventDefault();
  const email = document.getElementById('email');
  const pw = document.getElementById('password');
  const emailErr = document.getElementById('email-error');
  const pwErr = document.getElementById('pw-error');
  let valid = true;

  // Reset
  emailErr.classList.remove('show');
  pwErr.classList.remove('show');
  email.style.borderColor = '';
  pw.style.borderColor = '';

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if(!email.value || !emailRegex.test(email.value)){
    emailErr.classList.add('show');
    email.style.borderColor = 'var(--primary)';
    valid = false;
  }
  if(!pw.value || pw.value.length < 1){
    pwErr.classList.add('show');
    pw.style.borderColor = 'var(--primary)';
    valid = false;
  }
  if(!valid) return;

  // Simulate submit
  const btn = document.getElementById('submit-btn');
  btn.disabled = true;
  btn.textContent = 'Logging in...';
  setTimeout(()=>{
    btn.disabled = false;
    btn.textContent = 'Log in';
    document.getElementById('success-msg').classList.add('show');
    setTimeout(()=>{ window.location.href='index.html'; }, 1800);
  }, 1200);
}

// Social login simulation
function handleSocial(provider){
  const btn = event.currentTarget;
  const orig = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = `<span>Connecting to ${provider}...</span>`;
  setTimeout(()=>{
    btn.disabled = false;
    btn.innerHTML = orig;
    document.getElementById('success-msg').classList.add('show');
    setTimeout(()=>{ window.location.href='index.html'; }, 1800);
  }, 1500);
}
</script>
</body>
</html>
